$ErrorActionPreference='Stop'
$path='api/LuxuryApp.Application/Modules/RecursosHumanosLuxuryApp/Nomina/PeriodosNomina'
foreach($f in (Get-ChildItem $path -Recurse -Filter '*.cs')){$o=[IO.File]::ReadAllText($f.FullName);$n=$o.Replace('RecursosHumanosLuxuryApp.Nomina.PrestamosEmpleado','RecursosHumanosLuxuryApp.Nomina.PeriodosNomina');if($n-ne$o){[IO.File]::WriteAllText($f.FullName,$n,[Text.UTF8Encoding]::new($false))}}
$u='api/LuxuryApp.Application/GlobalUsings.cs';$o=[IO.File]::ReadAllText($u);$o=$o.Replace("global using RecursosHumanosLuxuryApp.Nomina.PrestamosEmpleado.DTOs;`r`n",'').Replace("global using RecursosHumanosLuxuryApp.Nomina.PrestamosEmpleado.Interfaces;`r`n",'');if($o -notmatch 'RecursosHumanosLuxuryApp.Nomina.PeriodosNomina.DTOs'){ $o=$o.Replace('global using RecursosHumanosLuxuryApp.Nomina.NominaDetalles.DTOs;','global using RecursosHumanosLuxuryApp.Nomina.PeriodosNomina.DTOs;`r`n'+'global using RecursosHumanosLuxuryApp.Nomina.NominaDetalles.DTOs;') };[IO.File]::WriteAllText($u,$o,[Text.UTF8Encoding]::new($false))
